-- ===========================================================================
-- 002_tables.sql — core tables.
-- ---------------------------------------------------------------------------
-- Legacy-format gotchas honoured EXACTLY:
--   * VARCHAR everywhere for categorical fields (NO native ENUM types), so the
--     legacy SharePoint "Choice" values migrate 1:1 without type coupling.
--   * inspection_log.log_id is GENERATED BY DEFAULT AS IDENTITY (NOT ALWAYS),
--     so the Glue backfill can INSERT explicit, per-plant-offset log_id values
--     (P1 +100000, P2 +200000) while normal app inserts still auto-generate.
--   * All sensor readings are NUMERIC (units are stripped on ingest; the DB
--     never stores "24.5 °C" strings — only 24.50).
-- Idempotent: CREATE TABLE IF NOT EXISTS + idempotent seed upserts.
-- ===========================================================================

SET search_path = srid, public;

-- --------------------------------------------------------------------------
-- sites — the two plants (P1, P2) and their server-room metadata.
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS srid.sites (
    site_id     INTEGER      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    site_code   VARCHAR(4)   NOT NULL UNIQUE,          -- 'P1' / 'P2'
    site_name   VARCHAR(120) NOT NULL,
    location    VARCHAR(120),
    room_label  VARCHAR(60),                            -- e.g. 'Server Room A'
    is_active    BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

COMMENT ON TABLE srid.sites IS 'MCF plants with a monitored server room (P1, P2).';

-- --------------------------------------------------------------------------
-- inspectors — AD-backed technicians. sam_account_name stored normalised
-- (UPPER) so lookups are effectively case-insensitive.
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS srid.inspectors (
    inspector_id     INTEGER     GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sam_account_name VARCHAR(32) NOT NULL UNIQUE,       -- e.g. 'YM2404031'
    display_name     VARCHAR(120),
    is_active        BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON COLUMN srid.inspectors.sam_account_name IS
  'sAMAccountName, stored UPPER-cased for case-insensitive matching.';

-- --------------------------------------------------------------------------
-- inspection_log — the core reading table (twice-daily per plant).
-- log_id is BIGINT identity GENERATED BY DEFAULT so Glue can insert explicit
-- offset ids. shift is VARCHAR ('AM' 08:00-10:00 / 'PM' 13:00-15:00).
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS srid.inspection_log (
    log_id           BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_site      VARCHAR(4)   NOT NULL
                       REFERENCES srid.sites (site_code),
    inspection_date  DATE         NOT NULL,
    shift            VARCHAR(2)   NOT NULL,             -- 'AM' / 'PM'
    inspected_at     TIMESTAMPTZ,
    inspector_id     INTEGER      REFERENCES srid.inspectors (inspector_id),
    sam_account_name VARCHAR(32),                       -- denormalised audit copy

    -- Sensor readings — always clean NUMERIC (units stripped on ingest).
    temperature_c    NUMERIC(5,2),
    humidity_pct     NUMERIC(5,2),
    ups1_voltage_v   NUMERIC(6,2),
    ups1_current_a   NUMERIC(6,2),
    ups2_voltage_v   NUMERIC(6,2),
    ups2_current_a   NUMERIC(6,2),

    status           VARCHAR(32),                       -- Choice text ('OK'...)
    flag             VARCHAR(32),                       -- derived/inbound flag
    raw_source       JSONB,                             -- original row, audit
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT uq_inspection UNIQUE (source_site, inspection_date, shift)
);

COMMENT ON TABLE srid.inspection_log IS
  'One row per plant per shift; log_id carries the per-plant migration offset.';
COMMENT ON COLUMN srid.inspection_log.log_id IS
  'GENERATED BY DEFAULT — Glue backfill inserts explicit offset ids (P1 +100000, P2 +200000).';

-- --------------------------------------------------------------------------
-- Seed the two plants (idempotent).
-- --------------------------------------------------------------------------
INSERT INTO srid.sites (site_code, site_name, location, room_label)
VALUES
    ('P1', 'MCF Plant 1', 'Jurong, SG', 'Server Room A'),
    ('P2', 'MCF Plant 2', 'Tuas, SG',   'Server Room B')
ON CONFLICT (site_code) DO NOTHING;
